mapper.select:
SELECT p.plan_id, p.plan_name, g.greenhouse_name, c.crop_name, c.variety_name, p.plan_status, p.planned_start_date, p.planned_end_date FROM cultivation_plan AS p JOIN greenhouse AS g ON g.greenhouse_id = p.greenhouse_id JOIN crop_stage_standard AS s ON s.standard_id = p.standard_id JOIN crop AS c ON c.crop_id = s.crop_id WHERE p.member_id = #{memberId}
AND g.greenhouse_name LIKE CONCAT('%', #{greenhouseName},'%')
AND c.crop_name LIKE CONCAT('%', #{cropName},'%')
AND c.variety_name LIKE CONCAT('%', #{varietyName},'%')
AND p.plan_status LIKE CONCAT('%', #{planStatus},'%')
ORDER BY p.plan_id DESC;
